public void testWriteToParcel() {
    $classUnderTest$ initialInput = $initializeClassUnderTest$;
    Parcel dest = Parcel.obtain();
    initialInput.writeToParcel(dest, 0);
    dest.setDataPosition(0);
    $classUnderTest$ unparcelled = $classUnderTest$.CREATOR.createFromParcel(dest);
    assertEquals(initialInput, unparcelled);
}
